/**
 * Inisialisasi Database Google Sheets & Akun Default
 */
function setupDatabase() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  
  var schema = {
    Users: ['UserID', 'Nama', 'Email', 'PasswordHash', 'Role', 'CreatedAt'],
    Meetings: ['MeetingID', 'HostUserID', 'Judul', 'StartTime', 'EndTime', 'Status'],
    Participants: ['ParticipantID', 'MeetingID', 'UserID', 'JoinTime', 'LeaveTime'],
    ChatMessages: ['MessageID', 'MeetingID', 'UserID', 'Message', 'SentAt'],
    AuditLog: ['LogID', 'Timestamp', 'UserID', 'Action', 'Details']
  };

  Object.keys(schema).forEach(function (sheetName) {
    var sheet = ss.getSheetByName(sheetName);
    var headers = schema[sheetName];
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(headers);
      sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');
    } else {
      // Ensure missing headers are preserved
      var existingHeaders = sheet.getRange(1, 1, 1, Math.max(1, sheet.getLastColumn())).getValues()[0];
      if (existingHeaders.length === 0 || existingHeaders[0] === '') {
        sheet.appendRow(headers);
        sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');
      }
    }
  });

  // Seed default Users if empty
  var usersSheet = ss.getSheetByName('Users');
  if (usersSheet.getLastRow() <= 1) {
    var defaultPasswordHash = hashPassword('Admin@2026');
    var now = new Date().toISOString();
    var defaultUsers = [
      ['USR-GURU-01', 'Bambang Sudarsono, M.Pd.', 'guru@edumeet.id', defaultPasswordHash, 'Guru', now],
      ['USR-GURU-02', 'Admin Pembelajaran', 'admin@edumeet.id', defaultPasswordHash, 'Guru', now],
      ['USR-PST-01', 'Ahmad Fauzan', 'peserta@edumeet.id', defaultPasswordHash, 'Peserta', now],
      ['USR-PST-02', 'Dewi Lestari', 'dewi@siswa.id', defaultPasswordHash, 'Peserta', now]
    ];
    defaultUsers.forEach(function (row) {
      usersSheet.appendRow(row);
    });
  }

  return { success: true, message: 'Database EduMeet berhasil disiapkan dengan akun default Admin@2026.' };
}

/**
 * Hashing Password SHA-256
 */
function hashPassword(password) {
  var digest = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(password || ''), Utilities.Charset.UTF_8);
  return digest.map(function (byte) {
    var b = (byte < 0 ? byte + 256 : byte).toString(16);
    return b.length === 1 ? '0' + b : b;
  }).join('');
}

/**
 * Sanitasi string input
 */
function sanitizeInput(val) {
  if (val === null || val === undefined) return '';
  return String(val).trim();
}

/**
 * Rate Limiting Login
 */
function checkLoginRateLimit(identifier) {
  var cache = CacheService.getScriptCache();
  var key = 'rate_limit_' + identifier;
  var attempts = parseInt(cache.get(key) || '0', 10);
  return attempts >= 5;
}

function recordLoginFailure(identifier) {
  var cache = CacheService.getScriptCache();
  var key = 'rate_limit_' + identifier;
  var attempts = parseInt(cache.get(key) || '0', 10) + 1;
  cache.put(key, String(attempts), 900); // 15 menit
}

function clearLoginFailures(identifier) {
  var cache = CacheService.getScriptCache();
  cache.remove('rate_limit_' + identifier);
}

/**
 * Audit Logging
 */
function logAction(userId, action, details) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('AuditLog');
    if (sheet) {
      var logId = 'LOG-' + Utilities.getUuid().substring(0, 8);
      sheet.appendRow([logId, new Date().toISOString(), userId || 'ANONYMOUS', action, JSON.stringify(details || {})]);
    }
  } catch (e) {
    console.error('AuditLog error: ' + e);
  }
}

/**
 * Sesi Token Backend (8 Jam)
 */
function generateSessionToken(userData) {
  var token = Utilities.getUuid();
  var cache = CacheService.getScriptCache();
  cache.put('session_' + token, JSON.stringify(userData), 28800); // 8 jam
  return token;
}

function validateSession(token) {
  if (!token) {
    return { valid: false, message: 'Token sesi tidak ditemukan. Silakan login kembali.' };
  }
  var cache = CacheService.getScriptCache();
  var sessionData = cache.get('session_' + token);
  if (!sessionData) {
    return { valid: false, message: 'Sesi Anda telah kedaluwarsa. Silakan login kembali.' };
  }
  try {
    return { valid: true, user: JSON.parse(sessionData) };
  } catch (e) {
    return { valid: false, message: 'Format sesi tidak valid.' };
  }
}

function destroySession(token) {
  if (token) {
    CacheService.getScriptCache().remove('session_' + token);
  }
  return { success: true };
}

/**
 * Helper Map Kolom Header
 */
function getColumnMap(sheet) {
  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  var map = {};
  headers.forEach(function (h, idx) {
    map[String(h).trim()] = idx;
  });
  return map;
}

/**
 * Otentikasi Login Pengguna
 */
function loginUser(payload) {
  payload = payload || {};
  var username = sanitizeInput(payload.username).toLowerCase();
  var password = String(payload.password || '');

  if (!username || !password) {
    return { success: false, message: 'Email/Username dan Password wajib diisi.' };
  }

  if (checkLoginRateLimit(username)) {
    return { success: false, message: 'Terlalu banyak percobaan gagal. Silakan tunggu 15 menit.' };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  if (!sheet || sheet.getLastRow() <= 1) {
    setupDatabase();
    sheet = ss.getSheetByName('Users');
  }

  var col = getColumnMap(sheet);
  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();
  var inputHash = hashPassword(password);
  var matchedUser = null;

  for (var i = 0; i < data.length; i++) {
    var row = data[i];
    var emailVal = String(row[col['Email']] || '').toLowerCase().trim();
    var userIdVal = String(row[col['UserID']] || '').toLowerCase().trim();
    var pwdHash = String(row[col['PasswordHash']] || '');

    if (emailVal === username || userIdVal === username) {
      if (pwdHash === inputHash) {
        matchedUser = {
          userId: String(row[col['UserID']]),
          fullname: String(row[col['Nama']]),
          email: String(row[col['Email']]),
          role: String(row[col['Role']])
        };
        break;
      } else {
        recordLoginFailure(username);
        return { success: false, message: 'Kata sandi tidak sesuai.' };
      }
    }
  }

  if (!matchedUser) {
    recordLoginFailure(username);
    return { success: false, message: 'Akun dengan email/ID tersebut tidak ditemukan.' };
  }

  clearLoginFailures(username);
  var token = generateSessionToken(matchedUser);
  logAction(matchedUser.userId, 'LOGIN_SUCCESS', { email: matchedUser.email });

  return {
    success: true,
    token: token,
    user: matchedUser
  };
}

/**
 * Pendaftaran Pengguna Baru (Sign Up)
 */
function registerUser(payload) {
  payload = payload || {};
  var nama = sanitizeInput(payload.nama);
  var email = sanitizeInput(payload.email).toLowerCase();
  var password = String(payload.password || '');

  if (!nama || !email || !password) {
    return { success: false, message: 'Nama, Email, dan Kata Sandi wajib diisi.' };
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('Users');
    if (!sheet || sheet.getLastRow() <= 1) {
      setupDatabase();
      sheet = ss.getSheetByName('Users');
    }

    var col = getColumnMap(sheet);
    var data = sheet.getRange(2, 1, Math.max(1, sheet.getLastRow() - 1), sheet.getLastColumn()).getValues();

    // Cek duplikasi email
    for (var i = 0; i < data.length; i++) {
      if (data[i].length > 0 && String(data[i][col['Email']]).toLowerCase().trim() === email) {
        return { success: false, message: 'Email ini sudah terdaftar. Silakan Sign In.' };
      }
    }

    var newUserId = 'USR-PST-' + Math.floor(1000 + Math.random() * 9000);
    var pwdHash = hashPassword(password);
    var now = new Date().toISOString();

    sheet.appendRow([newUserId, nama, email, pwdHash, 'Peserta', now]);
    logAction(newUserId, 'REGISTER_USER', { email: email });

    var newUser = {
      userId: newUserId,
      fullname: nama,
      email: email,
      role: 'Peserta'
    };
    var token = generateSessionToken(newUser);

    return { success: true, token: token, user: newUser };
  } catch (err) {
    return { success: false, message: 'Gagal mendaftar: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Bergabung sebagai Tamu (Guest)
 */
function joinAsGuest(payload) {
  payload = payload || {};
  var nama = sanitizeInput(payload.nama) || 'Tamu';
  var meetingId = sanitizeInput(payload.meetingId).toUpperCase();
  
  if (!meetingId) {
    return { success: false, message: 'Meeting ID wajib diisi.' };
  }
  
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var meetSheet = ss.getSheetByName('Meetings');
  if (!meetSheet || meetSheet.getLastRow() <= 1) {
    return { success: false, message: 'Meeting ID tidak ditemukan.' };
  }
  
  var mCol = getColumnMap(meetSheet);
  var meetData = meetSheet.getRange(2, 1, meetSheet.getLastRow() - 1, meetSheet.getLastColumn()).getValues();
  var targetMeeting = null;
  for (var i = 0; i < meetData.length; i++) {
    if (String(meetData[i][mCol['MeetingID']]).toUpperCase() === meetingId) {
       targetMeeting = { Status: String(meetData[i][mCol['Status']]) };
       break;
    }
  }
  
  if (!targetMeeting) return { success: false, message: 'Meeting ID tidak ditemukan.' };
  if (targetMeeting.Status === 'Ended') return { success: false, message: 'Kelas ini telah berakhir.' };
  
  var guestId = 'GST-' + Utilities.getUuid().substring(0, 8);
  var tempUser = {
    userId: guestId,
    fullname: nama,
    email: guestId + '@guest.local',
    role: 'Peserta'
  };
  
  var token = generateSessionToken(tempUser);
  return { success: true, token: token, user: tempUser };
}

/**
 * Mengambil Daftar Kelas (Meetings)
 */
function getMeetingsData(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var meetSheet = ss.getSheetByName('Meetings');
  var userSheet = ss.getSheetByName('Users');
  var partSheet = ss.getSheetByName('Participants');

  if (!meetSheet || meetSheet.getLastRow() <= 1) {
    return { success: true, data: [] };
  }

  var meetCol = getColumnMap(meetSheet);
  var meetData = meetSheet.getRange(2, 1, meetSheet.getLastRow() - 1, meetSheet.getLastColumn()).getValues();

  var userMap = {};
  if (userSheet && userSheet.getLastRow() > 1) {
    var uCol = getColumnMap(userSheet);
    var uData = userSheet.getRange(2, 1, userSheet.getLastRow() - 1, userSheet.getLastColumn()).getValues();
    uData.forEach(function (r) {
      userMap[String(r[uCol['UserID']])] = String(r[uCol['Nama']]);
    });
  }

  // Hitung partisipan
  var participantCountMap = {};
  var userAttendedMeetings = {};
  if (partSheet && partSheet.getLastRow() > 1) {
    var pCol = getColumnMap(partSheet);
    var pData = partSheet.getRange(2, 1, partSheet.getLastRow() - 1, partSheet.getLastColumn()).getValues();
    pData.forEach(function (pr) {
      var mid = String(pr[pCol['MeetingID']]);
      var uid = String(pr[pCol['UserID']]);
      participantCountMap[mid] = (participantCountMap[mid] || 0) + 1;
      if (uid === session.user.userId) {
        userAttendedMeetings[mid] = true;
      }
    });
  }

  var results = [];
  meetData.forEach(function (r) {
    var mid = String(r[meetCol['MeetingID']]);
    var hostId = String(r[meetCol['HostUserID']]);
    var status = String(r[meetCol['Status']] || 'Active');

    // Filter rule: Peserta pada halaman history hanya melihat kelas yang pernah diikutinya
    if (session.user.role === 'Peserta' && status === 'Ended' && !userAttendedMeetings[mid]) {
      return;
    }
    // Filter rule: Guru pada history hanya melihat kelas buatannya
    if (session.user.role === 'Guru' && status === 'Ended' && hostId !== session.user.userId) {
      return;
    }

    results.push({
      MeetingID: mid,
      HostUserID: hostId,
      HostName: userMap[hostId] || 'Guru Pengajar',
      Judul: String(r[meetCol['Judul']] || ''),
      StartTime: r[meetCol['StartTime']] ? new Date(r[meetCol['StartTime']]).toISOString() : '',
      EndTime: r[meetCol['EndTime']] ? new Date(r[meetCol['EndTime']]).toISOString() : '',
      Status: status,
      ParticipantCount: participantCountMap[mid] || 0
    });
  });

  results.sort(function (a, b) {
    return new Date(b.StartTime) - new Date(a.StartTime);
  });

  return { success: true, data: results };
}

/**
 * Membuat Kelas Pembelajaran Baru (Guru Host)
 */
function createMeeting(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (session.user.role !== 'Guru') {
    return { success: false, message: 'Hanya Guru yang memiliki akses untuk membuat ruang kelas.' };
  }

  payload = payload || {};
  var judul = sanitizeInput(payload.Judul);
  var meetingId = sanitizeInput(payload.MeetingID).toUpperCase() || ('KELAS-' + Math.floor(1000 + Math.random() * 9000));

  if (!judul) {
    return { success: false, message: 'Judul pembelajaran wajib diisi.' };
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var meetSheet = ss.getSheetByName('Meetings');
    var partSheet = ss.getSheetByName('Participants');

    // Cek ID duplikat
    if (meetSheet.getLastRow() > 1) {
      var mCol = getColumnMap(meetSheet);
      var ids = meetSheet.getRange(2, mCol['MeetingID'] + 1, meetSheet.getLastRow() - 1, 1).getValues();
      for (var i = 0; i < ids.length; i++) {
        if (String(ids[i][0]).toUpperCase() === meetingId) {
          meetingId = 'KELAS-' + Math.floor(1000 + Math.random() * 9000);
          break;
        }
      }
    }

    var now = new Date().toISOString();
    var newMeetingRow = [meetingId, session.user.userId, judul, now, '', 'Active'];
    meetSheet.appendRow(newMeetingRow);

    // Otomatis daftarkan Guru sebagai partisipan pertama
    var partId = 'PART-' + Utilities.getUuid().substring(0, 8);
    partSheet.appendRow([partId, meetingId, session.user.userId, now, '']);

    logAction(session.user.userId, 'CREATE_MEETING', { meetingId: meetingId, judul: judul });

    return {
      success: true,
      meeting: {
        MeetingID: meetingId,
        HostUserID: session.user.userId,
        Judul: judul,
        StartTime: now,
        EndTime: '',
        Status: 'Active'
      },
      participant: {
        ParticipantID: partId,
        MeetingID: meetingId,
        UserID: session.user.userId,
        JoinTime: now,
        LeaveTime: ''
      }
    };
  } catch (err) {
    return { success: false, message: 'Gagal membuat kelas: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Bergabung ke Kelas Lewat Meeting ID
 */
function joinMeeting(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  payload = payload || {};
  var meetingId = sanitizeInput(payload.MeetingID).toUpperCase();
  if (!meetingId) {
    return { success: false, message: 'Meeting ID wajib diisi.' };
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var meetSheet = ss.getSheetByName('Meetings');
    var partSheet = ss.getSheetByName('Participants');

    var mCol = getColumnMap(meetSheet);
    var meetData = meetSheet.getRange(2, 1, meetSheet.getLastRow() - 1, meetSheet.getLastColumn()).getValues();

    var targetMeeting = null;
    for (var i = 0; i < meetData.length; i++) {
      if (String(meetData[i][mCol['MeetingID']]).toUpperCase() === meetingId) {
        targetMeeting = {
          MeetingID: String(meetData[i][mCol['MeetingID']]),
          HostUserID: String(meetData[i][mCol['HostUserID']]),
          Judul: String(meetData[i][mCol['Judul']]),
          StartTime: meetData[i][mCol['StartTime']] ? new Date(meetData[i][mCol['StartTime']]).toISOString() : '',
          EndTime: meetData[i][mCol['EndTime']] ? new Date(meetData[i][mCol['EndTime']]).toISOString() : '',
          Status: String(meetData[i][mCol['Status']])
        };
        break;
      }
    }

    if (!targetMeeting) {
      return { success: false, message: 'Meeting ID tidak ditemukan.' };
    }

    if (targetMeeting.Status === 'Ended') {
      return { success: false, message: 'Kelas ini telah berakhir dan tidak dapat menerima peserta baru.' };
    }

    if (partSheet.getLastRow() > 1) {
      var pCol = getColumnMap(partSheet);
      var pData = partSheet.getRange(2, 1, partSheet.getLastRow() - 1, partSheet.getLastColumn()).getValues();
      for (var j = 0; j < pData.length; j++) {
        if (String(pData[j][pCol['MeetingID']]) === targetMeeting.MeetingID &&
            String(pData[j][pCol['UserID']]) === session.user.userId &&
            !pData[j][pCol['LeaveTime']]) {
          return {
            success: true,
            meeting: targetMeeting,
            participant: {
              ParticipantID: String(pData[j][pCol['ParticipantID']]),
              MeetingID: targetMeeting.MeetingID,
              UserID: session.user.userId,
              JoinTime: String(pData[j][pCol['JoinTime']]),
              LeaveTime: ''
            }
          };
        }
      }
    }

    // Catat kehadiran peserta baru
    var now = new Date().toISOString();
    var partId = 'PART-' + Utilities.getUuid().substring(0, 8);
    partSheet.appendRow([partId, targetMeeting.MeetingID, session.user.userId, now, '']);

    logAction(session.user.userId, 'JOIN_MEETING', { meetingId: targetMeeting.MeetingID });

    return {
      success: true,
      meeting: targetMeeting,
      participant: {
        ParticipantID: partId,
        MeetingID: targetMeeting.MeetingID,
        UserID: session.user.userId,
        JoinTime: now,
        LeaveTime: ''
      }
    };
  } catch (err) {
    return { success: false, message: 'Gagal bergabung ke kelas: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Keluar dari Ruang Kelas (Memperbarui LeaveTime)
 */
function leaveMeeting(token, participantId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (!participantId) return { success: true };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var partSheet = ss.getSheetByName('Participants');
    if (!partSheet || partSheet.getLastRow() <= 1) return { success: true };

    var pCol = getColumnMap(partSheet);
    var data = partSheet.getRange(2, 1, partSheet.getLastRow() - 1, partSheet.getLastColumn()).getValues();
    var now = new Date().toISOString();

    for (var i = 0; i < data.length; i++) {
      if (String(data[i][pCol['ParticipantID']]) === participantId) {
        partSheet.getRange(i + 2, pCol['LeaveTime'] + 1).setValue(now);
        break;
      }
    }

    logAction(session.user.userId, 'LEAVE_MEETING', { participantId: participantId });
    return { success: true };
  } catch (e) {
    return { success: false, message: e.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Mengakhiri Kelas (Host Guru Only)
 */
function endMeeting(token, meetingId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var meetSheet = ss.getSheetByName('Meetings');
    var partSheet = ss.getSheetByName('Participants');

    var mCol = getColumnMap(meetSheet);
    var mData = meetSheet.getRange(2, 1, meetSheet.getLastRow() - 1, meetSheet.getLastColumn()).getValues();
    var rowIndex = -1;
    var hostId = '';

    for (var i = 0; i < mData.length; i++) {
      if (String(mData[i][mCol['MeetingID']]) === meetingId) {
        rowIndex = i + 2;
        hostId = String(mData[i][mCol['HostUserID']]);
        break;
      }
    }

    if (rowIndex === -1) {
      return { success: false, message: 'Ruang kelas tidak ditemukan.' };
    }

    if (session.user.userId !== hostId && session.user.role !== 'Guru') {
      return { success: false, message: 'Hanya Guru pembuat kelas yang dapat mengakhiri sesi pembelajaran ini.' };
    }

    var now = new Date().toISOString();
    meetSheet.getRange(rowIndex, mCol['Status'] + 1).setValue('Ended');
    meetSheet.getRange(rowIndex, mCol['EndTime'] + 1).setValue(now);

    // Tutup seluruh partisipan yang masih aktif di kelas
    if (partSheet && partSheet.getLastRow() > 1) {
      var pCol = getColumnMap(partSheet);
      var pData = partSheet.getRange(2, 1, partSheet.getLastRow() - 1, partSheet.getLastColumn()).getValues();
      for (var j = 0; j < pData.length; j++) {
        if (String(pData[j][pCol['MeetingID']]) === meetingId && !pData[j][pCol['LeaveTime']]) {
          partSheet.getRange(j + 2, pCol['LeaveTime'] + 1).setValue(now);
        }
      }
    }

    logAction(session.user.userId, 'END_MEETING', { meetingId: meetingId });
    return { success: true, message: 'Kelas berhasil diakhiri.' };
  } catch (err) {
    return { success: false, message: 'Gagal mengakhiri kelas: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Mengambil Obrolan Chat Meeting
 */
function getMeetingChat(token, meetingId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var chatSheet = ss.getSheetByName('ChatMessages');
  var userSheet = ss.getSheetByName('Users');

  if (!chatSheet || chatSheet.getLastRow() <= 1) {
    return { success: true, data: [] };
  }

  var userMap = {};
  if (userSheet && userSheet.getLastRow() > 1) {
    var uCol = getColumnMap(userSheet);
    var uData = userSheet.getRange(2, 1, userSheet.getLastRow() - 1, userSheet.getLastColumn()).getValues();
    uData.forEach(function (r) {
      userMap[String(r[uCol['UserID']])] = String(r[uCol['Nama']]);
    });
  }

  var cCol = getColumnMap(chatSheet);
  var cData = chatSheet.getRange(2, 1, chatSheet.getLastRow() - 1, chatSheet.getLastColumn()).getValues();
  var messages = [];

  cData.forEach(function (r) {
    if (String(r[cCol['MeetingID']]) === meetingId) {
      var uid = String(r[cCol['UserID']]);
      messages.push({
        MessageID: String(r[cCol['MessageID']]),
        MeetingID: meetingId,
        UserID: uid,
        Nama: userMap[uid] || 'Peserta',
        Message: String(r[cCol['Message']] || ''),
        SentAt: r[cCol['SentAt']] ? new Date(r[cCol['SentAt']]).toISOString() : ''
      });
    }
  });

  return { success: true, data: messages };
}

/**
 * Mengirim Pesan Chat Baru
 */
function sendChatMessage(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  payload = payload || {};
  var meetingId = sanitizeInput(payload.MeetingID);
  var messageText = sanitizeInput(payload.Message);

  if (!meetingId || !messageText) {
    return { success: false, message: 'Pesan obrolan tidak boleh kosong.' };
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(5000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var chatSheet = ss.getSheetByName('ChatMessages');
    var msgId = 'MSG-' + Utilities.getUuid().substring(0, 8);
    var now = new Date().toISOString();

    chatSheet.appendRow([msgId, meetingId, session.user.userId, messageText, now]);

    return {
      success: true,
      message: {
        MessageID: msgId,
        MeetingID: meetingId,
        UserID: session.user.userId,
        Nama: session.user.fullname,
        Message: messageText,
        SentAt: now
      }
    };
  } catch (err) {
    return { success: false, message: 'Gagal mengirim pesan: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Mengambil Daftar Presensi Peserta Kelas
 */
function getMeetingAttendance(token, meetingId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var partSheet = ss.getSheetByName('Participants');
  var userSheet = ss.getSheetByName('Users');

  if (!partSheet || partSheet.getLastRow() <= 1) {
    return { success: true, data: [] };
  }

  var userMap = {};
  if (userSheet && userSheet.getLastRow() > 1) {
    var uCol = getColumnMap(userSheet);
    var uData = userSheet.getRange(2, 1, userSheet.getLastRow() - 1, userSheet.getLastColumn()).getValues();
    uData.forEach(function (r) {
      userMap[String(r[uCol['UserID']])] = String(r[uCol['Nama']]);
    });
  }

  var pCol = getColumnMap(partSheet);
  var pData = partSheet.getRange(2, 1, partSheet.getLastRow() - 1, partSheet.getLastColumn()).getValues();
  var attendance = [];

  pData.forEach(function (r) {
    if (String(r[pCol['MeetingID']]) === meetingId) {
      var uid = String(r[pCol['UserID']]);
      attendance.push({
        ParticipantID: String(r[pCol['ParticipantID']]),
        MeetingID: meetingId,
        UserID: uid,
        Nama: userMap[uid] || uid,
        JoinTime: r[pCol['JoinTime']] ? new Date(r[pCol['JoinTime']]).toISOString() : '',
        LeaveTime: r[pCol['LeaveTime']] ? new Date(r[pCol['LeaveTime']]).toISOString() : ''
      });
    }
  });

  return { success: true, data: attendance };
}

/**
 * Mengambil Semua Data Pengguna (Hanya Guru)
 */
function getUsers(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (session.user.role !== 'Guru') {
    return { success: false, message: 'Akses ditolak.' };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Users');
  if (!sheet || sheet.getLastRow() <= 1) {
    return { success: true, data: [] };
  }

  var col = getColumnMap(sheet);
  var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();
  var users = [];

  data.forEach(function (r) {
    users.push({
      UserID: String(r[col['UserID']]),
      Nama: String(r[col['Nama']]),
      Email: String(r[col['Email']]),
      Role: String(r[col['Role']]),
      CreatedAt: r[col['CreatedAt']] ? new Date(r[col['CreatedAt']]).toISOString() : ''
    });
  });

  return { success: true, data: users };
}

/**
 * Menambahkan Akun Pengguna Baru
 */
function addUser(token, payload) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  if (session.user.role !== 'Guru') {
    return { success: false, message: 'Hanya Guru yang dapat mendaftarkan pengguna baru.' };
  }

  payload = payload || {};
  var nama = sanitizeInput(payload.Nama);
  var email = sanitizeInput(payload.Email).toLowerCase();
  var role = sanitizeInput(payload.Role) || 'Peserta';

  if (!nama || !email) {
    return { success: false, message: 'Nama dan Email wajib diisi.' };
  }

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('Users');
    var col = getColumnMap(sheet);
    var data = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();

    for (var i = 0; i < data.length; i++) {
      if (String(data[i][col['Email']]).toLowerCase().trim() === email) {
        return { success: false, message: 'Pengguna dengan email ini sudah terdaftar.' };
      }
    }

    var prefix = role === 'Guru' ? 'USR-GURU-' : 'USR-PST-';
    var newUserId = prefix + Math.floor(1000 + Math.random() * 9000);
    var defaultHash = hashPassword('Admin@2026');
    var now = new Date().toISOString();

    sheet.appendRow([newUserId, nama, email, defaultHash, role, now]);
    logAction(session.user.userId, 'ADD_USER', { targetUserId: newUserId, email: email, role: role });

    return {
      success: true,
      data: {
        UserID: newUserId,
        Nama: nama,
        Email: email,
        Role: role,
        CreatedAt: now
      }
    };
  } catch (err) {
    return { success: false, message: 'Gagal menambahkan akun: ' + err.message };
  } finally {
    lock.releaseLock();
  }
}
